#include <stdio.h>

#define NEED 10000
#define KEEP 20000

int a[KEEP + 1], b[KEEP + 1];

int main(void) {
    int N, M;
    if (scanf("%d", &N) != 1) return 0;
    if (scanf("%d", &M) != 1) return 0;

    /* We only need the first 10000 final survivors. Since one turn with
       T >= 2 removes at most half of the list, keeping the first 20000
       elements of the current list at each step guarantees at least
       10000 survivors after every turn, and positions in the prefix
       coincide with positions in the full list. */
    int cur = N < KEEP ? N : KEEP;
    for (int i = 1; i <= cur; i++) a[i] = i;

    for (int m = 0; m < M && cur > 0; m++) {
        int T;
        if (scanf("%d", &T) != 1) break;
        int c = 0;
        for (int i = 1; i <= cur; i++) {
            if (i % T != 0) b[++c] = a[i];
        }
        for (int i = 1; i <= c; i++) a[i] = b[i];
        cur = c;
    }

    int out = cur < NEED ? cur : NEED;
    for (int i = 1; i <= out; i++) printf("%d\n", a[i]);

    return 0;
}
